PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE "instruments" ("instrument_id" TEXT PRIMARY KEY, "title" TEXT, "jurisdiction" TEXT, "jurisdiction_level" TEXT, "issuing_body" TEXT, "instrument_type" TEXT, "instrument_date" TEXT, "date_precision" TEXT, "date_text" TEXT, "date_basis" TEXT, "document_status" TEXT, "legal_effect" TEXT, "status_detail" TEXT, "scope" TEXT, "implementation_status" TEXT, "primary_source_id" TEXT, "primary_source_url" TEXT, "review_depth" TEXT, "current_status_limit" TEXT, "checked_date" TEXT, "coding_method" TEXT, "instrument_family" TEXT, "operative_status" TEXT, "commencement_text" TEXT, FOREIGN KEY("primary_source_id") REFERENCES "sources"("source_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "instrument_domains" ("domain_id" TEXT PRIMARY KEY, "instrument_id" TEXT, "domain" TEXT, "basis" TEXT, FOREIGN KEY("instrument_id") REFERENCES "instruments"("instrument_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "provisions" ("provision_id" TEXT PRIMARY KEY, "instrument_id" TEXT, "dimension" TEXT, "presence" TEXT, "summary" TEXT, "provision_force" TEXT, "locator" TEXT, "source_id" TEXT, "evidence_id" TEXT, "unknown_basis" TEXT, "implementation_verified" INTEGER, FOREIGN KEY("instrument_id") REFERENCES "instruments"("instrument_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("source_id") REFERENCES "sources"("source_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("evidence_id") REFERENCES "evidence"("evidence_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "sources" ("source_id" TEXT PRIMARY KEY, "title" TEXT, "url" TEXT, "source_type" TEXT, "is_cached" INTEGER, "retrieval_basis" TEXT, "reviewed_text_sha256" TEXT, "retrieved_characters" TEXT, "snapshot" TEXT);
CREATE TABLE "instrument_sources" ("instrument_source_id" TEXT PRIMARY KEY, "instrument_id" TEXT, "source_id" TEXT, "role" TEXT, FOREIGN KEY("instrument_id") REFERENCES "instruments"("instrument_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("source_id") REFERENCES "sources"("source_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "evidence" ("evidence_id" TEXT PRIMARY KEY, "instrument_id" TEXT, "provision_id" TEXT, "source_id" TEXT, "quote" TEXT, "locator" TEXT, "supports" TEXT, FOREIGN KEY("instrument_id") REFERENCES "instruments"("instrument_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("source_id") REFERENCES "sources"("source_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("provision_id") REFERENCES "provisions"("provision_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "system_links" ("system_link_id" TEXT PRIMARY KEY, "instrument_id" TEXT, "system_id" TEXT, "link_type" TEXT, "rationale" TEXT, "instrument_evidence_ids" TEXT, "system_assertion_ids" TEXT, "system_source_ids" TEXT, "system_source_urls" TEXT, "applicability_determination" TEXT, "checked_date" TEXT, FOREIGN KEY("instrument_id") REFERENCES "instruments"("instrument_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("system_id") REFERENCES "system_keys"("system_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "instrument_relationships" ("relationship_id" TEXT PRIMARY KEY, "instrument_id" TEXT, "related_instrument_id" TEXT, "relation_type" TEXT, "basis" TEXT, "legal_consequence" TEXT, FOREIGN KEY("instrument_id") REFERENCES "instruments"("instrument_id") DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY("related_instrument_id") REFERENCES "instruments"("instrument_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "jurisdiction_coverage" ("coverage_id" TEXT PRIMARY KEY, "jurisdiction" TEXT, "jurisdiction_level" TEXT, "queries" TEXT, "screening_status" TEXT, "included_instrument_ids" TEXT, "coverage_limit" TEXT, "checked_date" TEXT);
CREATE TABLE "candidate_decisions" ("decision_id" TEXT PRIMARY KEY, "candidate" TEXT, "decision" TEXT, "reason" TEXT);
CREATE TABLE "system_keys" ("system_id" TEXT PRIMARY KEY, "name" TEXT, "sector" TEXT, "jurisdiction" TEXT, "owner_institution_id" TEXT, "registry_version" TEXT);
COMMIT;
